@pytest.mark.parametrize("failure", ["backward", "nonfinite_result"]) def test_retained_exception_releases_only_the_estimators_owned_tensor_locals( estimator, monkeypatch, failure ): """An exception may remain logged. Its estimator frame must not retain our tape/workspace.
Deeper torch and caller frames can retain their own references; this test deliberately makes no assertion about those. The caller-supplied model itself remains live and unchanged. """ model = make_model() gradient = torch.autograd.grad
def fail(*args, **kwargs): if failure == "backward": raise RuntimeError("retained fixture backward exception") values = gradient(*args, **kwargs) return tuple(value * float("nan") for value in values)
monkeypatch.setattr(torch.autograd, "grad", fail) with pytest.raises(RuntimeError) as caught: estimator(model, PROMPT, [1, 3], target_layer=4, dim_batch=7) traceback = caught.value.__traceback__ # Deliberately retain the exception and its frames. owned_frame = None while traceback is not None: if traceback.tb_frame.f_code is estimator.__code__: owned_frame = traceback.tb_frame break traceback = traceback.tb_next assert owned_frame is not None owned_locals = owned_frame.f_locals retained = [ path for name, value in owned_locals.items() if name != "model" for path in tensor_paths(value, name) ] > assert retained == [], f"estimator exception frame retained owned tensors: {retained}" E AssertionError: estimator exception frame retained owned tensors: ['ids', 'mask', 'positions', 'maps[1]', 'maps[3]', 'target_positions', 'source_positions[0]', 'source_positions[1]', 'row_indices'] E assert ['ids', 'mask...sitions', ...] == [] E E Left contains 9 more items, first extra item: 'ids' E Use -v to get more diff
